INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7350646, 1149849, 96751, '<td valign="top">I wish we had this sort of wonder in the U.S.</td>', 'I wish we had this sort of wonder in the U.S.', '2015-05-15 01:24:25.000000', NULL, 1),
(7350647, 1149861, 96751, '<td valign="top">Feels so familiar. Like I was here when it was open...</td>', 'Feels so familiar. Like I was here when it was open...', '2015-05-15 01:25:06.000000', NULL, 1),
(7350648, 1149743, 96751, '<td valign="top">LOL at the title!!!</td>', 'LOL at the title!!!', '2015-05-15 01:26:21.000000', NULL, 1),
(7350649, 1149870, 96751, '<td valign="top">Love the weave of the metal and the colors.</td>', 'Love the weave of the metal and the colors.', '2015-05-15 01:26:59.000000', NULL, 1),
(7350650, 1149707, 96751, '<td valign="top">Old architecture is so much more emotional than most of the modern stuff...</td>', 'Old architecture is so much more emotional than most of the modern stuff...', '2015-05-15 01:27:52.000000', NULL, 1),
(7350651, 1149852, 96751, '<td valign="top">In a couple of years, it will have been swallowed by the grass</td>', 'In a couple of years, it will have been swallowed by the grass', '2015-05-15 01:28:51.000000', NULL, 1),
(7350652, 1149880, 96751, '<td valign="top">I want to go shooting here!!!</td>', 'I want to go shooting here!!!', '2015-05-15 01:29:13.000000', NULL, 1),
(7350653, 1149822, 96751, '<td valign="top">The resident ghost takes a photo</td>', 'The resident ghost takes a photo', '2015-05-15 01:29:58.000000', NULL, 1),
(7350654, 1149619, 96751, '<td valign="top">How quaint</td>', 'How quaint', '2015-05-15 01:30:23.000000', NULL, 1),
(7350656, 1149566, 96751, '<td valign="top">A really marvelous find, but I wish it popped from the background. I understand that it''s a metaphor for it disappearing physically, but I don''t think it works for the photograph</td>', 'A really marvelous find, but I wish it popped from the background. I understand that it''s a metaphor for it disappearing physically, but I don''t think it works for the photograph', '2015-05-15 01:32:06.000000', NULL, 1),
(7350657, 1149684, 96751, '<td valign="top">I would love to have seen this after the sun went down. Get a glow going</td>', 'I would love to have seen this after the sun went down. Get a glow going', '2015-05-15 01:33:31.000000', NULL, 1),
(7350658, 1149817, 96751, '<td valign="top">That''s some pretty cool wall art</td>', 'That''s some pretty cool wall art', '2015-05-15 01:33:55.000000', NULL, 1),
(7350659, 1149840, 96751, '<td valign="top">This is so peaceful</td>', 'This is so peaceful', '2015-05-15 01:34:15.000000', NULL, 1),
(7350660, 1149625, 96751, '<td valign="top">Ha! Sure is.   What a marvelous wreck</td>', 'Ha! Sure is.   What a marvelous wreck', '2015-05-15 01:34:40.000000', NULL, 1),
(7350661, 1149901, 96751, '<td valign="top">The hand of time claiming it''s victim.  Totally makes the photo.</td>', 'The hand of time claiming it''s victim.  Totally makes the photo.', '2015-05-15 01:35:33.000000', NULL, 1),
(7350662, 1149871, 96751, '<td valign="top">Magnificent. This structure has marvelous bones</td>', 'Magnificent. This structure has marvelous bones', '2015-05-15 01:36:17.000000', NULL, 1),
(7350663, 1149806, 96751, '<td valign="top">WOW!  Where is this????? how fascinating. I want to go here after dark :)</td>', 'WOW!  Where is this????? how fascinating. I want to go here after dark :)', '2015-05-15 01:37:05.000000', NULL, 1),
(7350664, 1149661, 96751, '<td valign="top">This is where haunting starts</td>', 'This is where haunting starts', '2015-05-15 01:37:34.000000', NULL, 1),
(7350666, 1149834, 96751, '<td valign="top">I love that broken window. It looks like a bird. Or a head. Fit for the noir mystery that is this image.</td>', 'I love that broken window. It looks like a bird. Or a head. Fit for the noir mystery that is this image.', '2015-05-15 01:38:53.000000', NULL, 1),
(7350667, 1149721, 96751, '<td valign="top">I have never seen one of those...</td>', 'I have never seen one of those...', '2015-05-15 01:40:02.000000', NULL, 1),
(7350669, 1149823, 96751, '<td valign="top">What an interesting juxtaposition</td>', 'What an interesting juxtaposition', '2015-05-15 01:40:44.000000', NULL, 1),
(7350671, 1149838, 96751, '<td valign="top">Hehehe. I was going to here, too :)</td>', 'Hehehe. I was going to here, too :)', '2015-05-15 01:44:06.000000', NULL, 1),
(7350673, 1149826, 96751, '<td valign="top">Wonderful, gentle touch with your pp''g. Perfect for this delicate creation.</td>', 'Wonderful, gentle touch with your pp''g. Perfect for this delicate creation.', '2015-05-15 01:46:29.000000', NULL, 1),
(7350675, 1149519, 96751, '<td valign="top">I would love to see outtakes from this location. Did you try anything from inside the structure? Or near it?</td>', 'I would love to see outtakes from this location. Did you try anything from inside the structure? Or near it?', '2015-05-15 01:47:44.000000', NULL, 1),
(7350676, 1149858, 96751, '<td valign="top">HOw lovely. The flowers really cheer up the place</td>', 'HOw lovely. The flowers really cheer up the place', '2015-05-15 01:49:19.000000', NULL, 1),
(7350677, 1149899, 96751, '<td valign="top">What are those magnificent pompom umbrellas????? I want some! This is my personal favorite of the challenge. Because there IS an abandoned building but it comes with the most adorable gendarmes.</td>', 'What are those magnificent pompom umbrellas????? I want some! This is my personal favorite of the challenge. Because there IS an abandoned building but it comes with the most adorable gendarmes.', '2015-05-15 01:52:03.000000', NULL, 1),
(7350678, 1149715, 96751, '<td valign="top">Oh, that light</td>', 'Oh, that light', '2015-05-15 01:52:47.000000', NULL, 1),
(7350679, 1149578, 96751, '<td valign="top">That''s just sad. I love the colorful roller</td>', 'That''s just sad. I love the colorful roller', '2015-05-15 01:54:16.000000', NULL, 1),
(7350680, 1149780, 96751, '<td valign="top">Wonderful title. And the chimney looks like a ghost watching over its past</td>', 'Wonderful title. And the chimney looks like a ghost watching over its past', '2015-05-15 01:55:22.000000', NULL, 1),
(7350730, 1149578, 177322, '<td valign="top">HDR works perfectly for this sort of falling-to-ruins setting. Nice framing with the entryway adding a second frame for the eye to explore. Impressive technical skills and eye.  Good luck.</td>', 'HDR works perfectly for this sort of falling-to-ruins setting. Nice framing with the entryway adding a second frame for the eye to explore. Impressive technical skills and eye.  Good luck.', '2015-05-15 10:52:19.000000', NULL, 1),
(7350731, 1149786, 177322, '<td valign="top">How tragic these magnificent buildings are allowed to rot as agrarian practices shift and decline.  Looks like that high sun was not exactly your friend with this shot but you managed it quite well. There are some itsy-bitsy sensor dust spots suggesting you may want to clean your sensor.  Otherwise, this is a nice tribute to a once majestic barn.</td>', 'How tragic these magnificent buildings are allowed to rot as agrarian practices shift and decline.  Looks like that high sun was not exactly your friend with this shot but you managed it quite well. There are some itsy-bitsy sensor dust spots suggesting you may want to clean your sensor.  Otherwise, this is a nice tribute to a once majestic barn.', '2015-05-15 11:01:44.000000', NULL, 1),
(7350734, 1149826, 177322, '<td valign="top">Commendable B&amp;W work - subject is certainly apropos for it. <br/> <br/>Instinctively, I keep scrolling up to catch more of the top of the window and the rotting curtain which makes me wonder if a portrait orientation might have been worth considering.  However, the landscape orientation does force the eye immediately to the wooden seat, the peeling wall covering and that rotten window sill, which are all most interesting, and nicely framed with the delicate, repetitive wallpaper design.  Ah, I may have just answered my own question about your choice of orientation. :-)  <br/> <br/>Fascinating study.  Good eye.</td>', 'Commendable B&W work - subject is certainly apropos for it.  Instinctively, I keep scrolling up to catch more of the top of the window and the rotting curtain which makes me wonder if a portrait orientation might have been worth considering.  However, the landscape orientation does force the eye immediately to the wooden seat, the peeling wall covering and that rotten window sill, which are all most interesting, and nicely framed with the delicate, repetitive wallpaper design.  Ah, I may have just answered my own question about your choice of orientation. :-)   Fascinating study.  Good eye.', '2015-05-15 11:10:37.000000', NULL, 1),
(7350735, 1149861, 177322, '<td valign="top">The title says it all.<br/> <br/>The textures are fabulous - from the plywood, to the glass, to the door knob, to the wire grating.  Lots of interest with nails sticking out, that ledge, even the weeds!  Good angle, because I suspect from a flat front capture, all those textures would have been subdued.<br/> <br/>Well done.</td>', 'The title says it all. The textures are fabulous - from the plywood, to the glass, to the door knob, to the wire grating.  Lots of interest with nails sticking out, that ledge, even the weeds!  Good angle, because I suspect from a flat front capture, all those textures would have been subdued. Well done.', '2015-05-15 11:14:58.000000', NULL, 1),
(7350736, 1149519, 177322, '<td valign="top">Great title!<br/> <br/>What a mysterious place.  It looks like it may have been claimed by fire and never rebuilt?  Good POV choice to emphasize the "openness" of the remaining structure. <br/> <br/>While the processing certainly accents the structures, it created some funky, unnatural clouds.<br/> <br/>Still, a nice find for this challenge.  Good luck.</td>', 'Great title! What a mysterious place.  It looks like it may have been claimed by fire and never rebuilt?  Good POV choice to emphasize the "openness" of the remaining structure.  While the processing certainly accents the structures, it created some funky, unnatural clouds. Still, a nice find for this challenge.  Good luck.', '2015-05-15 11:20:20.000000', NULL, 1),
(7350742, 1149736, 177322, '<td valign="top">The simplicity of the structure and its apparent isolation contributes to the poignancy of this capture. Overall it seems so sad, then that red thing in the upper window catches the eye and the serenity is jolted.  It is like a red ghost defiantly challenging the viewer.<br/> <br/>The HDR worked exceptionally well to create the popping colors of the wood and emphasize the textures of the metal roof and cement foundation. Good framing for working in a heavily wooded area.  Nice work.</td>', 'The simplicity of the structure and its apparent isolation contributes to the poignancy of this capture. Overall it seems so sad, then that red thing in the upper window catches the eye and the serenity is jolted.  It is like a red ghost defiantly challenging the viewer. The HDR worked exceptionally well to create the popping colors of the wood and emphasize the textures of the metal roof and cement foundation. Good framing for working in a heavily wooded area.  Nice work.', '2015-05-15 11:39:28.000000', NULL, 1),
(7350748, 1149675, 177322, '<td valign="top">What I expected to find in this challenge was buildings treated with HDR-on-steroids topped with tumultuous skies.<br/> <br/>This is such a serene interpretation of the challenge with accurate color and textures framed with pretty blue skies.  Composition, clarity, PoV - all spot on.<br/> <br/>I''m not voting in this challenge, but if I were, it would earn an eight from me.</td>', 'What I expected to find in this challenge was buildings treated with HDR-on-steroids topped with tumultuous skies. This is such a serene interpretation of the challenge with accurate color and textures framed with pretty blue skies.  Composition, clarity, PoV - all spot on. I''m not voting in this challenge, but if I were, it would earn an eight from me.', '2015-05-15 11:50:53.000000', NULL, 1),
(7350768, 1149823, 153814, '<td valign="top">Best in show if you ask me.<br/>Very well done.</td>', 'Best in show if you ask me.Very well done.', '2015-05-15 12:36:15.000000', NULL, 1),
(7350776, 1149684, 16046, '<td valign="top">Best in show award,congratulations</td>', 'Best in show award,congratulations', '2015-05-15 13:34:34.000000', NULL, 1),
(7350777, 1149806, 16046, '<td valign="top">Top 2</td>', 'Top 2', '2015-05-15 13:34:57.000000', NULL, 1),
(7350778, 1149901, 177322, '<td valign="top">That creepy hand?  Is it a shadow or something painted on the building? If it was staged for the shoot, my personal opinion is that it distracts from the ruin of the building.<br/> <br/>Having said that, the lighting set-up for this night shot captures the failure of the structure and all the textures of such dilapidation.  Additionally, it is an excellent demonstration your skill at handling night shots. The hard light off to the right of the frame is very effective. <br/> <br/>Technically, well executed - except for the hand - and a creative interpretation for this challenge. <br/> <br/><i>If you did not add the hand, my apologies for nagging on it. </i></td>', 'That creepy hand?  Is it a shadow or something painted on the building? If it was staged for the shoot, my personal opinion is that it distracts from the ruin of the building. Having said that, the lighting set-up for this night shot captures the failure of the structure and all the textures of such dilapidation.  Additionally, it is an excellent demonstration your skill at handling night shots. The hard light off to the right of the frame is very effective.  Technically, well executed - except for the hand - and a creative interpretation for this challenge.  If you did not add the hand, my apologies for nagging on it. ', '2015-05-15 13:39:33.000000', NULL, 1),
(7350779, 1149849, 177322, '<td valign="top">Good interpretation of a familiar landmark.  The PoV certainly adds to its stature.  Wish there was just a tad more tonality, but it looks like you were dealing with a broody sky so I appreciate what tones you were able to achieve.  Hard to believe, in a land where buildings/structures stand for centuries, this relative new one (erected in 1830''s) has fallen to such decay.  Nice tribute.</td>', 'Good interpretation of a familiar landmark.  The PoV certainly adds to its stature.  Wish there was just a tad more tonality, but it looks like you were dealing with a broody sky so I appreciate what tones you were able to achieve.  Hard to believe, in a land where buildings/structures stand for centuries, this relative new one (erected in 1830''s) has fallen to such decay.  Nice tribute.', '2015-05-15 13:48:37.000000', NULL, 1),
(7350781, 1149889, 114225, '<td valign="top">This is a great view point.</td>', 'This is a great view point.', '2015-05-15 14:40:10.000000', NULL, 1),
(7350782, 1149899, 114225, '<td valign="top">Vegetation around abandoned buildings always seems the most depressing.</td>', 'Vegetation around abandoned buildings always seems the most depressing.', '2015-05-15 14:40:39.000000', NULL, 1),
(7350783, 1149736, 114225, '<td valign="top">The upper window is creepy.</td>', 'The upper window is creepy.', '2015-05-15 14:41:21.000000', NULL, 1),
(7350784, 1149806, 114225, '<td valign="top">Wow, straight out the walking dead.</td>', 'Wow, straight out the walking dead.', '2015-05-15 14:44:00.000000', NULL, 1),
(7350791, 1149806, 112739, '<td valign="top">What an odd scene to behold. Almost new looking homes with no paved street. Not fond of the very heavy boarder/vignette, but I love the image. 8</td>', 'What an odd scene to behold. Almost new looking homes with no paved street. Not fond of the very heavy boarder/vignette, but I love the image. 8', '2015-05-15 15:53:01.000000', NULL, 1),
(7350792, 1149786, 112739, '<td valign="top">excellent example!</td>', 'excellent example!', '2015-05-15 15:53:32.000000', NULL, 1),
(7350793, 1149743, 112739, '<td valign="top">The fence really adds another dimension to this image. So spooky and mysterious. Excellent image. 9</td>', 'The fence really adds another dimension to this image. So spooky and mysterious. Excellent image. 9', '2015-05-15 15:55:28.000000', NULL, 1),
(7350794, 1149901, 112739, '<td valign="top">I think someone had a hand in the abandonment of this place. Looks cursed to me.</td>', 'I think someone had a hand in the abandonment of this place. Looks cursed to me.', '2015-05-15 16:00:37.000000', NULL, 1),
(7350835, 1149861, 3306, '<td valign="top">Good subject. I think I would like it better with a tighter crop.</td>', 'Good subject. I think I would like it better with a tighter crop.', '2015-05-15 20:47:19.000000', NULL, 1),
(7350844, 1149822, 104230, '<td valign="top">Great use of your and the outdoor reflection (on double paned glass by the look of it).</td>', 'Great use of your and the outdoor reflection (on double paned glass by the look of it).', '2015-05-15 23:40:39.000000', NULL, 1),
(7350847, 1149806, 177322, '<td valign="top">These are fairly new homes!  It would be very interesting to learn the story behind this haunting scene.  <br/> <br/>While I like what the toning had done to the structures and the land, the sky looks unworldly; however, this is an unworldly scene, so maybe it fits.  Some may find the vignette disruptive, but I have the opinion it adds a "vintage" feel to a modern setting.  I like the way the mud "street" pulls one''s eye through the image. <br/> <br/>Desperately sad situation - unfortunately, well suited for this challenge.  Good choice.</td>', 'These are fairly new homes!  It would be very interesting to learn the story behind this haunting scene.   While I like what the toning had done to the structures and the land, the sky looks unworldly; however, this is an unworldly scene, so maybe it fits.  Some may find the vignette disruptive, but I have the opinion it adds a "vintage" feel to a modern setting.  I like the way the mud "street" pulls one''s eye through the image.  Desperately sad situation - unfortunately, well suited for this challenge.  Good choice.', '2015-05-16 00:10:58.000000', NULL, 1),
(7350848, 1149661, 177322, '<td valign="top">Many titles in this challenge convey sadness; coupled with the neglect and decay in <u>this</u> image, I think it is the saddest. <br/> <br/>Personally, I would have cloned out those distracting pieces of white trash on the ground. It is, nonetheless, an effective image with the chosen angle of the structure, the slightly elevated PoV, and the boarded windows - even the one that has fallen away.<br/> <br/>Very appropriate submission for this challenge.</td>', 'Many titles in this challenge convey sadness; coupled with the neglect and decay in this image, I think it is the saddest.  Personally, I would have cloned out those distracting pieces of white trash on the ground. It is, nonetheless, an effective image with the chosen angle of the structure, the slightly elevated PoV, and the boarded windows - even the one that has fallen away. Very appropriate submission for this challenge.', '2015-05-16 00:20:00.000000', NULL, 1),
(7350849, 1149787, 177322, '<td valign="top">It better be a very quick decision by the looks of the leaning supports!  <br/> <br/>This image is interesting in that it captures property in addition to the building that has fallen to ruin and neglect.  What a unique building, too. One can''t help but ponder what its original use was.<br/> <br/>Good choice for this challenge.</td>', 'It better be a very quick decision by the looks of the leaning supports!   This image is interesting in that it captures property in addition to the building that has fallen to ruin and neglect.  What a unique building, too. One can''t help but ponder what its original use was. Good choice for this challenge.', '2015-05-16 00:26:39.000000', NULL, 1),
(7350850, 1149871, 177322, '<td valign="top">With the hard, straight lines on the left and the impression of curves via the "ribs" on the right, there is a some visual discordance. That is not the fault of the photographer; it appears to be the work of a storm.<br/> <br/>In the end it becomes a study of incongruent shapes which is brilliantly presented with the use of B&amp;W.  The inharmonious lines are unsettling and you presented that tension effectively.<br/> <br/>A good choice for this challenge.</td>', 'With the hard, straight lines on the left and the impression of curves via the "ribs" on the right, there is a some visual discordance. That is not the fault of the photographer; it appears to be the work of a storm. In the end it becomes a study of incongruent shapes which is brilliantly presented with the use of B&W.  The inharmonious lines are unsettling and you presented that tension effectively. A good choice for this challenge.', '2015-05-16 00:40:46.000000', NULL, 1),
(7350852, 1149894, 177322, '<td valign="top">Oh my, what a behemoth!  <br/> <br/>The color saturation certainly emphasizes the rust. Effectively composed.  Not necessarily very emotive, but it certainly conveys the hard facts of abandonment. <br/> <br/>One of my favorite titles in this challenge.</td>', 'Oh my, what a behemoth!   The color saturation certainly emphasizes the rust. Effectively composed.  Not necessarily very emotive, but it certainly conveys the hard facts of abandonment.  One of my favorite titles in this challenge.', '2015-05-16 00:47:41.000000', NULL, 1),
(7350853, 1149902, 177322, '<td valign="top">Goodness!  You wouldn''t have to tell me twice to "stay out."  <br/> <br/>The neglect and resulting danger in the building is readily apparent.  Maybe this is just a tad over processed?  There is some sort of strange dark halo around the exposed rebars.  <br/> <br/>Still the subject was a good choice for this challenge.</td>', 'Goodness!  You wouldn''t have to tell me twice to "stay out."   The neglect and resulting danger in the building is readily apparent.  Maybe this is just a tad over processed?  There is some sort of strange dark halo around the exposed rebars.   Still the subject was a good choice for this challenge.', '2015-05-16 00:54:17.000000', NULL, 1),
(7350854, 1149880, 177322, '<td valign="top">Powerful lighting made even more muscular with the processing.  What a great man-made cavern to study for this challenge.  Good work.</td>', 'Powerful lighting made even more muscular with the processing.  What a great man-made cavern to study for this challenge.  Good work.', '2015-05-16 00:56:35.000000', NULL, 1),
(7350876, 1149871, 179852, '<td valign="top">very pleasing lines and angles</td>', 'very pleasing lines and angles', '2015-05-16 10:21:48.000000', NULL, 1),
(7350894, 1149566, 174417, '<td valign="top">I think the background and foreground blend too much together.  The building should be more prominent.</td>', 'I think the background and foreground blend too much together.  The building should be more prominent.', '2015-05-16 11:02:49.000000', NULL, 1),
(7350895, 1149519, 174417, '<td valign="top">I like your perspective of shooting low.</td>', 'I like your perspective of shooting low.', '2015-05-16 11:04:37.000000', NULL, 1),
(7350896, 1149822, 174417, '<td valign="top">In the future, you might want to straighten this photo.  The first thing that caught my eye was everything was tilted to the left.</td>', 'In the future, you might want to straighten this photo.  The first thing that caught my eye was everything was tilted to the left.', '2015-05-16 11:05:34.000000', NULL, 1),
(7350897, 1149861, 174417, '<td valign="top">Nice processing.</td>', 'Nice processing.', '2015-05-16 11:05:45.000000', NULL, 1),
(7350898, 1149884, 174417, '<td valign="top">Nice capture, but a little too much processing for my tastes.</td>', 'Nice capture, but a little too much processing for my tastes.', '2015-05-16 11:06:26.000000', NULL, 1),
(7350899, 1149826, 174417, '<td valign="top">Nicely captured.  B&amp;W fits this photo perfectly.</td>', 'Nicely captured.  B&W fits this photo perfectly.', '2015-05-16 11:06:58.000000', NULL, 1),
(7350933, 1149806, 173844, '<td valign="top">There''s a poignant, just-missed quality to this image, which elicits a deep sigh.  Seems to have run out of luck as much as financing.  The heavy, lowering sky,  suits the scene perfectly, the washed out coloration completing this enervating dream of never attaining your destination.  The vignette nicely serves the appearance of a post card. Excellent.</td>', 'There''s a poignant, just-missed quality to this image, which elicits a deep sigh.  Seems to have run out of luck as much as financing.  The heavy, lowering sky,  suits the scene perfectly, the washed out coloration completing this enervating dream of never attaining your destination.  The vignette nicely serves the appearance of a post card. Excellent.', '2015-05-16 16:45:01.000000', NULL, 1),
(7350936, 1149823, 173844, '<td valign="top">There''s a playful tension here between the genteel, black and white, aging house and the abundance of bright, cheerful roses.  And there''s a symmetry to the amount of area allotted to each.  The soft light enhances the delicacy of the scene.  I find the doorway roof structure unfortunate -- but what are you going to do?  Overall, very appealing.</td>', 'There''s a playful tension here between the genteel, black and white, aging house and the abundance of bright, cheerful roses.  And there''s a symmetry to the amount of area allotted to each.  The soft light enhances the delicacy of the scene.  I find the doorway roof structure unfortunate -- but what are you going to do?  Overall, very appealing.', '2015-05-16 17:02:25.000000', NULL, 1),
(7350937, 1149646, 173844, '<td valign="top">Adroitly handled, this massive structure is tucked behind the wedge of greenery and beside a large river to diminish its tendency to loom rather than participate in the whole.  Now we can admire its implacability only partially diminished by its unfortunate (well, not to the environment) decommission.  The grainy sky seems to be one last sooty fling.  The background to the left of the coal plant adds a delicate frill to the almost pointillist scene. Has a subtle beauty.</td>', 'Adroitly handled, this massive structure is tucked behind the wedge of greenery and beside a large river to diminish its tendency to loom rather than participate in the whole.  Now we can admire its implacability only partially diminished by its unfortunate (well, not to the environment) decommission.  The grainy sky seems to be one last sooty fling.  The background to the left of the coal plant adds a delicate frill to the almost pointillist scene. Has a subtle beauty.', '2015-05-16 17:17:53.000000', NULL, 1),
(7350938, 1149902, 173844, '<td valign="top">This abandoned building has devolved into a Mondrian stitched together by girders, columns and foliage, which affords a totally unexpected delight.  At first glance I wished for more sky, but now feel it makes a nice upper frame as it is, echoing the blues in the structure.  A real pleasure to gaze at.</td>', 'This abandoned building has devolved into a Mondrian stitched together by girders, columns and foliage, which affords a totally unexpected delight.  At first glance I wished for more sky, but now feel it makes a nice upper frame as it is, echoing the blues in the structure.  A real pleasure to gaze at.', '2015-05-16 17:26:07.000000', NULL, 1),
(7350940, 1149861, 173844, '<td valign="top">The line of structures is held together, in a way, by the parade of textures beautifully delineated by the black and white format.  The perspective draws the viewer right into the scene.  The contrast is attractive and fine-grained.  There''s a fussy harmony to all the windows and doors.  Makes a strong statement.</td>', 'The line of structures is held together, in a way, by the parade of textures beautifully delineated by the black and white format.  The perspective draws the viewer right into the scene.  The contrast is attractive and fine-grained.  There''s a fussy harmony to all the windows and doors.  Makes a strong statement.', '2015-05-16 17:40:44.000000', NULL, 1),
(7350942, 1149884, 173844, '<td valign="top">Seems more of a structure than a building, but still it''s a lovely image.  The beautiful detailed, glowing, rusting metal stands in strong counterpoint to the grim atmosphere.  The scene through the opening on the left is charming.</td>', 'Seems more of a structure than a building, but still it''s a lovely image.  The beautiful detailed, glowing, rusting metal stands in strong counterpoint to the grim atmosphere.  The scene through the opening on the left is charming.', '2015-05-16 17:51:34.000000', NULL, 1),
(7350971, 1149628, 177322, '<td valign="top">Having to visually work through the tendrils of the vegetation to get to the unkempt, neglected building is captured perfectly with the title.<br/> <br/>I make a complimentary nod to converting this busy image to B&amp;W.  Usually when I try to turn heavy vegetation to B&amp;W all I get is mud!  The remarkable tonal range identifies every little leaf and chip of paint.  <br/> <br/>It appears that you are shooting into the sun, but you have that under control, too.<br/> <br/>Your interpretation of the challenge is to be applauded.<br/> <br/>Well done.</td>', 'Having to visually work through the tendrils of the vegetation to get to the unkempt, neglected building is captured perfectly with the title. I make a complimentary nod to converting this busy image to B&W.  Usually when I try to turn heavy vegetation to B&W all I get is mud!  The remarkable tonal range identifies every little leaf and chip of paint.   It appears that you are shooting into the sun, but you have that under control, too. Your interpretation of the challenge is to be applauded. Well done.', '2015-05-16 23:52:07.000000', NULL, 1),
(7350972, 1149870, 177322, '<td valign="top">The hodgepodge of tin sheets, various colors, great textures and the refitted doorway make this almost a merry vision; yet, those very aspects point to an abandoned building.  Adept composition adds strength to this image.  Good eye!</td>', 'The hodgepodge of tin sheets, various colors, great textures and the refitted doorway make this almost a merry vision; yet, those very aspects point to an abandoned building.  Adept composition adds strength to this image.  Good eye!', '2015-05-16 23:57:00.000000', NULL, 1),
(7350973, 1149780, 177322, '<td valign="top">How sad.  So much decay here. Excellent choice for this challenge, nicely executed.  Good luck.</td>', 'How sad.  So much decay here. Excellent choice for this challenge, nicely executed.  Good luck.', '2015-05-16 23:58:05.000000', NULL, 1),
(7350975, 1149662, 177322, '<td valign="top">Clever title!<br/> <br/>The processing brings out the details of the decay and creates many places for the viewer to examine.<br/> <br/>Nicely framed.  Well seen.</td>', 'Clever title! The processing brings out the details of the decay and creates many places for the viewer to examine. Nicely framed.  Well seen.', '2015-05-17 00:12:42.000000', NULL, 1),
(7350976, 1149707, 177322, '<td valign="top">What an imposing building.  Perhaps the processing is a tad harsh in that it has done some funky things to the sky and created some dusky halos on the left of the image.  I would respectfully submit that the dark blue smudging at the top could have been entirely cropped out without impacting the presentation of the building. Otherwise it is a nice sharp image.  I like that you used the fence to frame the bottom.</td>', 'What an imposing building.  Perhaps the processing is a tad harsh in that it has done some funky things to the sky and created some dusky halos on the left of the image.  I would respectfully submit that the dark blue smudging at the top could have been entirely cropped out without impacting the presentation of the building. Otherwise it is a nice sharp image.  I like that you used the fence to frame the bottom.', '2015-05-17 00:18:45.000000', NULL, 1),
(7350977, 1149730, 177322, '<td valign="top">Methinks the renovation was done in a most haphazard manner.  Oh, dear...  <br/> <br/>Apropos title.  Good find.</td>', 'Methinks the renovation was done in a most haphazard manner.  Oh, dear...   Apropos title.  Good find.', '2015-05-17 00:23:36.000000', NULL, 1),
(7350978, 1149721, 177322, '<td valign="top">Actually, I sort of wish that black thing had been kicked out of the way or, minimally, cropped out because it really distracts from the point of the image - the abandoned building.  Or, maybe it was the intent to have the black thing there?  If so, I apologize for criticizing an artistic design.  Anyway, it is a perfect building for the challenge and the muscular processing emphasizes it''s decay.</td>', 'Actually, I sort of wish that black thing had been kicked out of the way or, minimally, cropped out because it really distracts from the point of the image - the abandoned building.  Or, maybe it was the intent to have the black thing there?  If so, I apologize for criticizing an artistic design.  Anyway, it is a perfect building for the challenge and the muscular processing emphasizes it''s decay.', '2015-05-17 00:31:09.000000', NULL, 1),
(7351011, 1149715, 177322, '<td valign="top">It would be really nice to see this on the front page. Compositionally it is top notch: finely balanced, strong leading lines, well lit, nicely processed, tack sharp.  Just superb technical work.  <br/> <br/>Where it goes wrong with me, personally, is the lack of pathos. It is clearly an abandoned, neglected building but there is nothing there to wrench the heart.  For me, it is simply too sterile.<br/> <br/>Don''t misunderstand, were I voting, this would be a nine from me simply on technical merits.  Quite sincerely, I hope this ribbons for you.  Best of luck.</td>', 'It would be really nice to see this on the front page. Compositionally it is top notch: finely balanced, strong leading lines, well lit, nicely processed, tack sharp.  Just superb technical work.   Where it goes wrong with me, personally, is the lack of pathos. It is clearly an abandoned, neglected building but there is nothing there to wrench the heart.  For me, it is simply too sterile. Don''t misunderstand, were I voting, this would be a nine from me simply on technical merits.  Quite sincerely, I hope this ribbons for you.  Best of luck.', '2015-05-17 11:35:24.000000', NULL, 1),
(7351012, 1149822, 177322, '<td valign="top">Please take no offense, but the photographer''s reflection in the window just doesn''t work for me.  Perhaps it was necessary to get an inside view, and the inside is clearly abandoned and quite apropos to the challenge, but I just wish that another method had been used to block the reflective quality of the glass panes.  I do like, as the title pronounces, that the viewer is directed through the structure right to another window.</td>', 'Please take no offense, but the photographer''s reflection in the window just doesn''t work for me.  Perhaps it was necessary to get an inside view, and the inside is clearly abandoned and quite apropos to the challenge, but I just wish that another method had been used to block the reflective quality of the glass panes.  I do like, as the title pronounces, that the viewer is directed through the structure right to another window.', '2015-05-17 11:36:26.000000', NULL, 1),
(7351013, 1149566, 177322, '<td valign="top">Overgrown ruins are always interesting, always make one wonder what happened. While intriguing, I''m not sure the structure itself stands out enough from the jungle to make it a strong image.  It appears that some selective desaturation was applied - maybe if the jungle had been desaturated and the structure slightly over saturated, it would have more impact?  Sorry, this image just doesn''t work for me.  Nonetheless, a jungle with ruins makes for all sorts of photo opportunities, how lucky for you.</td>', 'Overgrown ruins are always interesting, always make one wonder what happened. While intriguing, I''m not sure the structure itself stands out enough from the jungle to make it a strong image.  It appears that some selective desaturation was applied - maybe if the jungle had been desaturated and the structure slightly over saturated, it would have more impact?  Sorry, this image just doesn''t work for me.  Nonetheless, a jungle with ruins makes for all sorts of photo opportunities, how lucky for you.', '2015-05-17 11:50:31.000000', NULL, 1),
(7351034, 1149901, 163081, '<td valign="top">I guess some processing on the very clean white wall would change the impact of this wonderful shot. The sky is top. The creepy hand adds something extra. A 7 from me.</td>', 'I guess some processing on the very clean white wall would change the impact of this wonderful shot. The sky is top. The creepy hand adds something extra. A 7 from me.', '2015-05-17 14:35:32.000000', NULL, 1),
(7351035, 1149849, 163081, '<td valign="top">Love this image. Should score high. A 9 from me and in my top 3</td>', 'Love this image. Should score high. A 9 from me and in my top 3', '2015-05-17 14:37:09.000000', NULL, 1),
(7351038, 1149838, 163081, '<td valign="top">something''s weird in this picture. Looks like the girl is only a picture but her elbow sticks out the bars. A 6 from me.</td>', 'something''s weird in this picture. Looks like the girl is only a picture but her elbow sticks out the bars. A 6 from me.', '2015-05-17 14:39:40.000000', NULL, 1),
(7351039, 1149894, 163081, '<td valign="top">Yes, that''s what I wanted to see in this challenge. Rust, broken windows, graffiti, An 8 from me</td>', 'Yes, that''s what I wanted to see in this challenge. Rust, broken windows, graffiti, An 8 from me', '2015-05-17 14:41:39.000000', NULL, 1),
(7351077, 1149619, 177322, '<td valign="top">Probably the most unique building in this challenge!  The sun flare is a nice touch.  The framing is a little crowded on the left, and the ramshackle building on the right pulls the eye from the subject building, but there probably wasn''t much you could do about that. Good effort to capture this most unusual building.</td>', 'Probably the most unique building in this challenge!  The sun flare is a nice touch.  The framing is a little crowded on the left, and the ramshackle building on the right pulls the eye from the subject building, but there probably wasn''t much you could do about that. Good effort to capture this most unusual building.', '2015-05-17 18:34:42.000000', NULL, 1),
(7351079, 1149891, 177322, '<td valign="top">While the geometrically abstract quality of this image bade me to study it for quite a pause, in the end two aspects contributed to a less than satisfying experience: that metallic vertical object on the right side and its darkness.  Nonetheless, I like the punctuation of the dots of light and the orange and green rectangles, and it is an intriguing interpretation of this challenge.</td>', 'While the geometrically abstract quality of this image bade me to study it for quite a pause, in the end two aspects contributed to a less than satisfying experience: that metallic vertical object on the right side and its darkness.  Nonetheless, I like the punctuation of the dots of light and the orange and green rectangles, and it is an intriguing interpretation of this challenge.', '2015-05-17 18:41:48.000000', NULL, 1),
(7351086, 1149806, 38162, '<td valign="top">gives even more meaning to "the boring burbs" - wow - casualty of the banksters putting our economy in the ditch I take it.  the frame is needed to tie it all in - just a tad heavy with it for me.  toning is spot on.  a great statement image.  7.  gl</td>', 'gives even more meaning to "the boring burbs" - wow - casualty of the banksters putting our economy in the ditch I take it.  the frame is needed to tie it all in - just a tad heavy with it for me.  toning is spot on.  a great statement image.  7.  gl', '2015-05-17 20:21:42.000000', NULL, 1),
(7351087, 1149822, 38162, '<td valign="top">great idea!</td>', 'great idea!', '2015-05-17 20:24:40.000000', NULL, 1),
(7351119, 1149646, 38162, '<td valign="top">nicely composed - effect left lots of noise behind but that was your call - gl.</td>', 'nicely composed - effect left lots of noise behind but that was your call - gl.', '2015-05-17 22:57:27.000000', NULL, 1),
(7351145, 1149806, 113016, '<td valign="top">I love this...it makes me want to know the story.  good luck.  7</td>', 'I love this...it makes me want to know the story.  good luck.  7', '2015-05-18 00:21:07.000000', NULL, 1),
(7351218, 1149880, 118154, '<td valign="top">Best image here I think.</td>', 'Best image here I think.', '2015-05-18 07:34:59.000000', NULL, 1),
(7351219, 1149838, 118154, '<td valign="top">Impressed that you got Mila to model for you.</td>', 'Impressed that you got Mila to model for you.', '2015-05-18 07:36:14.000000', NULL, 1),
(7351220, 1149625, 114285, '<td valign="top">Looks like someone still might be there.</td>', 'Looks like someone still might be there.', '2015-05-18 07:51:15.000000', NULL, 1),
(7351252, 1149858, 113411, '<td valign="top">How beautiful !!!</td>', 'How beautiful !!!', '2015-05-18 10:46:47.000000', NULL, 1),
(7351255, 1149625, 113411, '<td valign="top"><strike></strike></td>', '', '2015-05-18 10:50:33.000000', NULL, 1),
(7351278, 1149601, 177322, '<td valign="top">For me personally, this image is too grainy and too high contrast.  Nonetheless, I applaud your interpretation of this challenge.</td>', 'For me personally, this image is too grainy and too high contrast.  Nonetheless, I applaud your interpretation of this challenge.', '2015-05-18 12:47:35.000000', NULL, 1),
(7351281, 1149899, 177322, '<td valign="top">While the subject building could be most interesting with the fallen bricks, cracked wall, bricked doorways, because it is the background the viewer''s eye is captured by the weed not the building.  Downright menacing weed, by the way.  Some sort of thistle?</td>', 'While the subject building could be most interesting with the fallen bricks, cracked wall, bricked doorways, because it is the background the viewer''s eye is captured by the weed not the building.  Downright menacing weed, by the way.  Some sort of thistle?', '2015-05-18 12:53:09.000000', NULL, 1),
(7351284, 1149878, 177322, '<td valign="top">The chosen treatment really brought out the marvelous grains of the wood.  Plenty of interesting things to explore between the stacked pallets, the crooked window and all the clutter on the roof. The vegetation lends to all the textures and the colors pop nicely. Well done.</td>', 'The chosen treatment really brought out the marvelous grains of the wood.  Plenty of interesting things to explore between the stacked pallets, the crooked window and all the clutter on the roof. The vegetation lends to all the textures and the colors pop nicely. Well done.', '2015-05-18 12:57:41.000000', NULL, 1),
(7351287, 1149783, 177322, '<td valign="top">The color boost nicely enhances the varied textures of the stone and tin.  Well framed.  The subtle vignette works, too.  Good choice for this challenge.</td>', 'The color boost nicely enhances the varied textures of the stone and tin.  Well framed.  The subtle vignette works, too.  Good choice for this challenge.', '2015-05-18 13:01:02.000000', NULL, 1),
(7351290, 1149726, 177322, '<td valign="top">The framing by the porch pillar and the tree coupled with the line of the step railing encourage the eye right up to the door. Very effective composition.  The overgrown bramble, the chipped paint and loss of one light all lend to the story. Nicely executed.  Good luck.</td>', 'The framing by the porch pillar and the tree coupled with the line of the step railing encourage the eye right up to the door. Very effective composition.  The overgrown bramble, the chipped paint and loss of one light all lend to the story. Nicely executed.  Good luck.', '2015-05-18 13:07:30.000000', NULL, 1),
(7351293, 1149743, 177322, '<td valign="top">Or is she still there?  The drape of that curtain suggests someone behind - watching.  Creepy.<br/> <br/>Your choice of waning/waxing daylight certainly lends to the spooky mood, and shooting the fence in the foreground suggests perhaps something is being contained behind? Probably the most eerie submission in this challenge. <br/> <br/>Lots of mood in this image.   Good luck with it.</td>', 'Or is she still there?  The drape of that curtain suggests someone behind - watching.  Creepy. Your choice of waning/waxing daylight certainly lends to the spooky mood, and shooting the fence in the foreground suggests perhaps something is being contained behind? Probably the most eerie submission in this challenge.  Lots of mood in this image.   Good luck with it.', '2015-05-18 13:13:41.000000', NULL, 1),
(7351297, 1149834, 177322, '<td valign="top">The selection of toning certainly compliments this image.  The cord (rope?) tying the doors and the broken window certainly tell the story and is nicely echoed in the title.  Well seen. Expertly presented.  Good luck.</td>', 'The selection of toning certainly compliments this image.  The cord (rope?) tying the doors and the broken window certainly tell the story and is nicely echoed in the title.  Well seen. Expertly presented.  Good luck.', '2015-05-18 13:23:07.000000', NULL, 1),
(7351302, 1149625, 177322, '<td valign="top">Succinctly, this deserves to ribbon. Best of luck.</td>', 'Succinctly, this deserves to ribbon. Best of luck.', '2015-05-18 13:30:34.000000', NULL, 1),
(7351307, 1149889, 177322, '<td valign="top">The strong vignette really emphasizes the building perfectly.  I like that this was shot effectively through a fence and vegetation.  Maybe I, personally, would have liked a touch more contrast, but the visual story still comes through.  The title adds depth to the image.</td>', 'The strong vignette really emphasizes the building perfectly.  I like that this was shot effectively through a fence and vegetation.  Maybe I, personally, would have liked a touch more contrast, but the visual story still comes through.  The title adds depth to the image.', '2015-05-18 13:34:03.000000', NULL, 1),
(7351371, 1149883, 177322, '<td valign="top">A good snapshot - and please do not be offended by that comment - but compared to other entries that are more highly processed and/or whose subject may be more melodramatic, I anticipate this image will not place well. Sorry, I''m not saying that to be mean.  Please take heart in the fact that this photo is sharp, well exposed and framed/composed appropriately.<br/> <br/>Please know, too, I am only commenting in this challenge, not voting.</td>', 'A good snapshot - and please do not be offended by that comment - but compared to other entries that are more highly processed and/or whose subject may be more melodramatic, I anticipate this image will not place well. Sorry, I''m not saying that to be mean.  Please take heart in the fact that this photo is sharp, well exposed and framed/composed appropriately. Please know, too, I am only commenting in this challenge, not voting.', '2015-05-18 18:23:13.000000', NULL, 1),
(7351377, 1149877, 177322, '<td valign="top">Coincidently, I shot a similar scene where a vine had grown in between two doors.  This is far superior to what I had but did not enter, btw. This is nicely processed to compliment the textures and capture the invading roots. The patchwork of the tin-mended window panes adds interest. I would very much like to see this on the front page.  Good luck!</td>', 'Coincidently, I shot a similar scene where a vine had grown in between two doors.  This is far superior to what I had but did not enter, btw. This is nicely processed to compliment the textures and capture the invading roots. The patchwork of the tin-mended window panes adds interest. I would very much like to see this on the front page.  Good luck!', '2015-05-18 18:40:02.000000', NULL, 1),
(7351378, 1149858, 177322, '<td valign="top">The pretty flower positioned against the unruly growth seen through the metal frame is an interesting study.</td>', 'The pretty flower positioned against the unruly growth seen through the metal frame is an interesting study.', '2015-05-18 18:44:15.000000', NULL, 1),
(7351379, 1149838, 177322, '<td valign="top">When I saw this thumbnail, I thought, "Ho hum, more graffiti."  Then I opened it and saw the girl - in a cage!!  <br/> <br/>Hard-hitting.  While it is on the verge of disturbing, I still want to keep studying it. The lighting - whether natural or set up, is highly effective. Very emotive image. <br/> <br/>Introducing the caged girl certainly adds a powerful interpretive twist to this challenge.<br/> <br/>Well done.</td>', 'When I saw this thumbnail, I thought, "Ho hum, more graffiti."  Then I opened it and saw the girl - in a cage!!   Hard-hitting.  While it is on the verge of disturbing, I still want to keep studying it. The lighting - whether natural or set up, is highly effective. Very emotive image.  Introducing the caged girl certainly adds a powerful interpretive twist to this challenge. Well done.', '2015-05-18 18:44:20.000000', NULL, 1),
(7351405, 1149884, 177322, '<td valign="top">Stunning! The brooding malevolence of the sky - just fabulous. Whether it meets the <i>"abandoned building"</i> specification... Well, I don''t care;  This shot is riveting.</td>', 'Stunning! The brooding malevolence of the sky - just fabulous. Whether it meets the "abandoned building" specification... Well, I don''t care;  This shot is riveting.', '2015-05-18 22:08:43.000000', NULL, 1),
(7351409, 1149535, 177322, '<td valign="top">The hole in the roof atop the broken out window is very effective.  For me, the graffiti takes away from that substance.  Although the PoV is a tad askew (which is your creative license), the image is nonetheless a well exposed, tack sharp, and compositionally interesting sans the graffiti.</td>', 'The hole in the roof atop the broken out window is very effective.  For me, the graffiti takes away from that substance.  Although the PoV is a tad askew (which is your creative license), the image is nonetheless a well exposed, tack sharp, and compositionally interesting sans the graffiti.', '2015-05-18 22:24:29.000000', NULL, 1),
(7351412, 1149840, 177322, '<td valign="top">That crimson froth of flowers in the foreground is such a foil to the blank stare of the boarded windows. The diagonal of the river running through the bottom of the frame adds interest as does the lowering (rising?) light.  Quite a captivating study.</td>', 'That crimson froth of flowers in the foreground is such a foil to the blank stare of the boarded windows. The diagonal of the river running through the bottom of the frame adds interest as does the lowering (rising?) light.  Quite a captivating study.', '2015-05-18 22:28:15.000000', NULL, 1),
(7351413, 1149684, 177322, '<td valign="top">The bright colors actually make this scene appear festive which provides an unexpected interpretive twist to this challenge.</td>', 'The bright colors actually make this scene appear festive which provides an unexpected interpretive twist to this challenge.', '2015-05-18 22:29:30.000000', NULL, 1),
(7351599, 1149822, 40391, '<td valign="top">So many layers, so intriguing, so much to enjoy, and so pleasantly unexpected in this challenge. So I like.</td>', 'So many layers, so intriguing, so much to enjoy, and so pleasantly unexpected in this challenge. So I like.', '2015-05-19 18:02:29.000000', NULL, 1),
(7351600, 1149834, 40391, '<td valign="top">I would have been tempted to title this No Exit :)<br/>Great find and nicely processed.</td>', 'I would have been tempted to title this No Exit :)Great find and nicely processed.', '2015-05-19 18:04:51.000000', NULL, 1),
(7351601, 1149823, 40391, '<td valign="top">This doesnt happen often but your title has added an additional level of emotion and created a greater appreciation, for me, of your image.</td>', 'This doesnt happen often but your title has added an additional level of emotion and created a greater appreciation, for me, of your image.', '2015-05-19 18:08:38.000000', NULL, 1),
