(7351610, 1149822, 19825, '<td valign="top">The most intriguing of the lot. Nicely done.</td>', 'The most intriguing of the lot. Nicely done.', '2015-05-19 19:37:27.000000', NULL, 1),
(7351611, 1149849, 19825, '<td valign="top">Stark and lonely. Lovely image.</td>', 'Stark and lonely. Lovely image.', '2015-05-19 19:38:28.000000', NULL, 1),
(7351612, 1149877, 19825, '<td valign="top">Decaying before our eyes.</td>', 'Decaying before our eyes.', '2015-05-19 19:39:04.000000', NULL, 1),
