(7351615, 1149891, 19825, '<td valign="top">Strangely captivating.</td>', 'Strangely captivating.', '2015-05-19 19:41:04.000000', NULL, 1),
(7351616, 1149780, 19825, '<td valign="top">I like the tones and textures.</td>', 'I like the tones and textures.', '2015-05-19 19:42:55.000000', NULL, 1),
(7351617, 1149715, 19825, '<td valign="top">Stark symmetry.</td>', 'Stark symmetry.', '2015-05-19 19:43:13.000000', NULL, 1),
