(7352347, 1149625, 97225, '<td valign="top">Fascinating - makes me think that this may have ''fallen down around their ears''. One of my ribbon picks.</td>', 'Fascinating - makes me think that this may have ''fallen down around their ears''. One of my ribbon picks.', '2015-05-22 00:53:16.000000', NULL, 1),
