(7352393, 1149901, 135744, '<td valign="top">Congrats on the ribbon. Very impressive photo. It takes a lot of skill to take a photo this good in low light.</td>', 'Congrats on the ribbon. Very impressive photo. It takes a lot of skill to take a photo this good in low light.', '2015-05-22 05:10:22.000000', NULL, 0),
(7352394, 1149806, 135744, '<td valign="top">Congrats on the ribbon. What an incredible place. Processing is just perfect.</td>', 'Congrats on the ribbon. What an incredible place. Processing is just perfect.', '2015-05-22 05:11:12.000000', NULL, 0),
(7352395, 1149519, 135744, '<td valign="top">Congrats on the HM. Looks a lot like one of the old tin mines in Cornwall (England). Very nicely captured and processed.</td>', 'Congrats on the HM. Looks a lot like one of the old tin mines in Cornwall (England). Very nicely captured and processed.', '2015-05-22 05:12:10.000000', NULL, 0),
