(7352398, 1149684, 138630, '<td valign="top">Nice find, capture, processing, Don.  Glad you got THAT out of your system :)  Congrats on the top ten.</td>', 'Nice find, capture, processing, Don.  Glad you got THAT out of your system :)  Congrats on the top ten.', '2015-05-22 08:27:30.000000', NULL, 0),
(7352405, 1149822, 156466, '<td valign="top">In my top 3.  Really thought this would have done better.  Nicely done regardless of finish.</td>', 'In my top 3.  Really thought this would have done better.  Nicely done regardless of finish.', '2015-05-22 09:26:32.000000', NULL, 0),
(7352417, 1149806, 97225, '<td valign="top">Congrats on the ribbon. Awesome entry. Incredible that such a development can just be abandoned.</td>', 'Congrats on the ribbon. Awesome entry. Incredible that such a development can just be abandoned.', '2015-05-22 10:24:32.000000', NULL, 0),
(7352426, 1149849, 2553, '<td valign="top">Congratulations!  I absolutely LOVE this image, definitely one of my favorites in the challenge.  Your angle makes it look very imposing and scary, and I just love the whole atmosphere of the image.</td>', 'Congratulations!  I absolutely LOVE this image, definitely one of my favorites in the challenge.  Your angle makes it look very imposing and scary, and I just love the whole atmosphere of the image.', '2015-05-22 11:20:38.000000', NULL, 0),
(7352428, 1149901, 2553, '<td valign="top">Congratulations!  I was honestly on the fence about the "hand".  I love the texture that you managed to capture in the front structure, but what REALLY was kind of freaky (to me) is that it looks like a very small window on the side by the hand and it looks like there is light coming from inside the building.   Don''t see light from the front, so i just couldn''t figure out where it was coming from.  Maybe the lights off to the right were shining through to that window.</td>', 'Congratulations!  I was honestly on the fence about the "hand".  I love the texture that you managed to capture in the front structure, but what REALLY was kind of freaky (to me) is that it looks like a very small window on the side by the hand and it looks like there is light coming from inside the building.   Don''t see light from the front, so i just couldn''t figure out where it was coming from.  Maybe the lights off to the right were shining through to that window.', '2015-05-22 11:27:10.000000', NULL, 0),
(7352457, 1149858, 113411, '<td valign="top">This is so underrated in mho. It looks like Fine Art to me.</td>', 'This is so underrated in mho. It looks like Fine Art to me.', '2015-05-22 12:03:37.000000', NULL, 0),
(7352476, 1149849, 173844, '<td valign="top">Well-deserved blue.  Congratulations!  Beautifully handled.</td>', 'Well-deserved blue.  Congratulations!  Beautifully handled.', '2015-05-22 13:01:55.000000', NULL, 0),
(7352478, 1149901, 173844, '<td valign="top">Congrats on winning the red.  You deserve a hand.</td>', 'Congrats on winning the red.  You deserve a hand.', '2015-05-22 13:03:55.000000', NULL, 0),
(7352483, 1149806, 173844, '<td valign="top">Congratulations on winning the yellow ribbon --   great photo.</td>', 'Congratulations on winning the yellow ribbon --   great photo.', '2015-05-22 13:12:10.000000', NULL, 0),
(7352486, 1149519, 173844, '<td valign="top">Congratulations on your high finish.  Charming image.  How neat that people can picnic here  --   can taste the watermelon...</td>', 'Congratulations on your high finish.  Charming image.  How neat that people can picnic here  --   can taste the watermelon...', '2015-05-22 13:17:58.000000', NULL, 0),
(7352487, 1149823, 173844, '<td valign="top">Congratulations on your high finish.  Uplifting, cozy image.</td>', 'Congratulations on your high finish.  Uplifting, cozy image.', '2015-05-22 13:22:20.000000', NULL, 0),
(7352494, 1149877, 173844, '<td valign="top">My comment got lost somehow, somehow meaning my own misstep.  I thought this was very strong, verging on an abstract.  I also noted the twining vine,roots and whatever, veering into sci-fi.  I happen to find the sign distracting.  Nice entry.</td>', 'My comment got lost somehow, somehow meaning my own misstep.  I thought this was very strong, verging on an abstract.  I also noted the twining vine,roots and whatever, veering into sci-fi.  I happen to find the sign distracting.  Nice entry.', '2015-05-22 13:40:54.000000', NULL, 0),
