(7352499, 1149901, 177322, '<td valign="top">Congrats!   And, a big wave to that hand!  Clearly, I was wrong.  :-)</td>', 'Congrats!   And, a big wave to that hand!  Clearly, I was wrong.  :-)', '2015-05-22 13:59:56.000000', NULL, 0),
(7352500, 1149806, 177322, '<td valign="top">Congrats!  Thanks, too, for sharing the story behind this tragic image.</td>', 'Congrats!  Thanks, too, for sharing the story behind this tragic image.', '2015-05-22 14:00:40.000000', NULL, 0),
(7352503, 1149519, 177322, '<td valign="top">Congrats!  In Wisconsin?  Wow - I guess it has been a <b>long</b> time since I''ve visited this beautiful state although for a brief time there was consideration of attending the Lumberjack competition in Hayward this year.  Anyway, I''ve digressed.... well deserved HM.</td>', 'Congrats!  In Wisconsin?  Wow - I guess it has been a long time since I''ve visited this beautiful state although for a brief time there was consideration of attending the Lumberjack competition in Hayward this year.  Anyway, I''ve digressed.... well deserved HM.', '2015-05-22 14:05:26.000000', NULL, 0),
(7352507, 1149849, 147314, '<td valign="top">Great location for the challenge and nice processing. Congrats on the Blue, Paul!</td>', 'Great location for the challenge and nice processing. Congrats on the Blue, Paul!', '2015-05-22 14:10:08.000000', NULL, 0),
(7352551, 1149661, 173844, '<td valign="top">My comment didn''t get through -- sorry.  Your title led my observations.  Mostly I felt the absence of the family, the bustling about, the children playing on the rock.  The fogginess frames the image in poignant loss.  The building seems to lean to the left with bated breath, as if there is a tomorrow.</td>', 'My comment didn''t get through -- sorry.  Your title led my observations.  Mostly I felt the absence of the family, the bustling about, the children playing on the rock.  The fogginess frames the image in poignant loss.  The building seems to lean to the left with bated breath, as if there is a tomorrow.', '2015-05-22 16:24:39.000000', NULL, 0),
(7352558, 1149891, 173844, '<td valign="top">I''m surprised that more people haven''t appreciated the beauty of this image.  I like the path you''ve taken here.</td>', 'I''m surprised that more people haven''t appreciated the beauty of this image.  I like the path you''ve taken here.', '2015-05-22 16:52:54.000000', NULL, 0),
(7352581, 1149806, 30049, '<td valign="top">Ha!  Look at you.  2nd challenge entry in 5 years and you pull a Ribbon out of one.  :)  Cool.  Congrats!</td>', 'Ha!  Look at you.  2nd challenge entry in 5 years and you pull a Ribbon out of one.  :)  Cool.  Congrats!', '2015-05-22 19:26:31.000000', NULL, 0),
